#!/usr/bin/env node
// Build the estate index in README.md from estate.json and repos/*/meta.json.
// The index sits between the BEGIN and END markers; the rest of README.md is hand-written.
// Usage: node build-index.mjs           rewrite the index in README.md
//        node build-index.mjs --check   exit 1 if the index is stale (CI)
import { existsSync, readdirSync, readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const root = join(dirname(fileURLToPath(import.meta.url)), "..", "..");
const BEGIN = "<!-- BEGIN estate index: generated by .github/scripts/build-index.mjs from estate.json and repos/*/meta.json. Do not edit by hand. -->";
const END = "<!-- END estate index -->";

const check = process.argv.includes("--check");
const estate = JSON.parse(readFileSync(join(root, "estate.json"), "utf8"));
const errors = [];

if (!estate.siteUrl?.endsWith("/")) errors.push("estate.json: siteUrl must end with '/'");

// Every repos/<name>/ directory needs exactly one index entry, and every entry a directory.
const dirs = readdirSync(join(root, "repos"), { withFileTypes: true })
  .filter((d) => d.isDirectory())
  .map((d) => d.name);
const listed = estate.areas.flatMap((a) => a.repos.map((r) => r.name));
for (const name of dirs) if (!listed.includes(name)) errors.push(`repos/${name}/ has no entry in estate.json`);
for (const name of listed) {
  if (listed.indexOf(name) !== listed.lastIndexOf(name)) errors.push(`estate.json lists ${name} twice`);
  if (!dirs.includes(name)) errors.push(`estate.json lists ${name}, but repos/${name}/ does not exist`);
}

function snapshot(name) {
  const file = join(root, "repos", name, "meta.json");
  if (!existsSync(file)) return errors.push(`repos/${name}/meta.json is missing`), null;
  const { gitCommitHash: sha, lastAnalyzedAt: at } = JSON.parse(readFileSync(file, "utf8"));
  if (!/^[0-9a-f]{40}$/.test(sha ?? "")) errors.push(`repos/${name}/meta.json: gitCommitHash is not a full SHA`);
  if (!/^\d{4}-\d{2}-\d{2}T/.test(at ?? "")) errors.push(`repos/${name}/meta.json: lastAnalyzedAt is not an ISO date`);
  return { sha, date: at?.slice(0, 10) };
}

const cell = (s) => s.replace(/\|/g, "\\|");

function row({ name, description }) {
  const snap = snapshot(name);
  if (!snap) return "";
  const source = `https://github.com/${estate.sourceOrg}/${name}`;
  const explore = [
    `[Viewer](${estate.siteUrl}${name}/)`,
    `[Onboarding](repos/${name}/ONBOARDING.md)`,
    `[README](repos/${name}/README.md)`,
    `[Source](${source})`,
  ].join(" · ");
  const commit = `[\`${snap.sha.slice(0, 7)}\`](${source}/commit/${snap.sha})`;
  return `| [${name}](repos/${name}/) | ${cell(description)} | ${explore} | ${snap.date}, ${commit} |`;
}

const sections = estate.areas.map((area) => {
  const lines = [`### ${area.title}`, ""];
  if (area.intro) lines.push(area.intro, "");
  lines.push("| Repo | What it is | Explore | Snapshot |", "|---|---|---|---|");
  lines.push(...area.repos.map(row));
  if (area.seeAlso) lines.push("", `Go deeper: ${area.seeAlso.map((l) => `[${l.text}](${l.url})`).join(" · ")}`);
  return lines.join("\n");
});

if (errors.length) {
  for (const e of errors) console.error(`error: ${e}`);
  process.exit(1);
}

const readmePath = join(root, "README.md");
const readme = readFileSync(readmePath, "utf8");
const start = readme.indexOf(BEGIN);
const stop = readme.indexOf(END);
if (start < 0 || stop < start) {
  console.error("error: README.md lacks the BEGIN/END estate index markers");
  process.exit(1);
}
const next = `${readme.slice(0, start)}${BEGIN}\n\n${sections.join("\n\n")}\n\n${readme.slice(stop)}`;

if (check) {
  if (next !== readme) {
    console.error("error: the README.md estate index is stale. Run: node .github/scripts/build-index.mjs");
    process.exit(1);
  }
  console.log(`estate index is current (${listed.length} repos)`);
} else {
  writeFileSync(readmePath, next);
  console.log(`wrote the estate index to README.md (${listed.length} repos)`);
}
